import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import type {ReactNode} from 'react';
import {View,Text,type ViewProps} from 'react-native';
import {InkAndLaserPointer,type InkAndLaserPointerProps} from '@/components/nyc-tron/ui/components/forge/slides/InkAndLaserPointer';
import {PointEditor2D,type EditorPoint2D} from '@/components/nyc-tron/ui/components/forge/inputs/PointEditor2D';
import {PropertyInspector} from '@/components/nyc-tron/ui/components/forge/inputs/PropertyInspector';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
export interface PDFSignatureArtifact {id:string;kind:'ink'|'image';label:string;aspectRatio:number}
export interface SignatureStampToolProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 mode:'ink'|'image';ink:Omit<InkAndLaserPointerProps,'capture'|'onCaptureStroke'>;
 artifact:PDFSignatureArtifact|null;placement:{pageId:string;x:number;y:number;width:number;rotation:number};
 canPlace:boolean;placedArtifactId?:string;onModeChange:(mode:'ink'|'image')=>void;
 onChooseImage:(signal?:AbortSignal)=>unknown;onCreateInkArtifact:(signal?:AbortSignal)=>unknown;
 onPlacementChange:(placement:SignatureStampToolProps['placement'],signal?:AbortSignal)=>unknown;
 onPlace:(artifactId:string,placement:SignatureStampToolProps['placement'],signal?:AbortSignal)=>unknown;
 renderPlacement:(artifact:PDFSignatureArtifact|null,placement:SignatureStampToolProps['placement'])=>ReactNode;unstyled?:boolean;
}
/** Visible signature stamp authoring. Certificate signing is a separate native PDF form workflow. */
export function SignatureStampTool({scope='pdf-signature',revision=0,...props}:SignatureStampToolProps){
 const {mode,ink,artifact,placement,canPlace,placedArtifactId,onModeChange:_mode,onChooseImage:_image,onCreateInkArtifact:_create,onPlacementChange:_placement,onPlace:_place,renderPlacement,unstyled=false,disabledReason,style,...rest}=props;
 if(!['ink','image'].includes(mode)||!placement.pageId.trim()||![placement.x,placement.y,placement.width,placement.rotation].every(Number.isFinite)||placement.x<0||placement.x>1||placement.y<0||placement.y>1||placement.width<.001||placement.width>1||placement.rotation< -180||placement.rotation>180||artifact&&(!artifact.id.trim()||!Number.isFinite(artifact.aspectRatio)||artifact.aspectRatio<=0||artifact.aspectRatio>1000))throw new RangeError('Invalid signature placement');
 const owner=JSON.stringify([...controlIdentity(scope,revision),placement.pageId,artifact?.id,disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined),off=guard.pending||disabledReason!==undefined;
 return <View {...rest} style={[{gap:8},style]} accessibilityLabel="PDF signature stamp"><View style={{flexDirection:'row',gap:8,flexWrap:'wrap'}}>{(['ink','image'] as const).map(m=><Button key={m} title={m==='ink'?'Draw signature':'Image signature'} variant="secondary" accessibilityState={{selected:m===mode}} disabled={off} unstyled={unstyled} onPress={()=>guard.current()?.onModeChange(m)}/>)}</View>
 {mode==='ink'?<><View style={{flexDirection:'row',gap:8}}>{(['pen','eraser'] as const).map(tool=><Button key={tool} title={tool==='pen'?'Signature pen':'Erase signature ink'} disabled={off} unstyled={unstyled} onPress={()=>guard.current()?.ink.onModeChange(tool)}/>)}</View><View style={{height:180,position:'relative'}}><InkAndLaserPointer {...ink} scope={scope} revision={revision} capture={false} disabled={off||ink.disabled} unstyled={unstyled}/></View><Button title="Create signature from drawn ink" disabled={off||ink.strokes.length===0} unstyled={unstyled} onPress={()=>guard.run('ink',(h,s)=>h.ink.strokes.length?h.onCreateInkArtifact(s):undefined)}/></>:<Button title="Choose signature image" disabled={off} unstyled={unstyled} onPress={()=>guard.run('image',(h,s)=>h.onChooseImage(s))}/>}
 <Text {...{className:unstyled?undefined:'text-text'}}>{artifact?artifact.label:'Create or choose a signature before placing it'}</Text>
 <PointEditor2D scope={scope} revision={revision} points={[{id:'stamp',label:'Stamp position',x:placement.x,y:placement.y}]} selectedId="stamp" onSelect={()=>{}} disabledReason={off?'Signature placement unavailable':undefined} unstyled={unstyled} renderPreview={points=>renderPlacement(artifact,{...placement,x:points[0]!.x,y:points[0]!.y})} onCommit={(point:EditorPoint2D)=>guard.run('placement',(h,s)=>h.onPlacementChange({...h.placement,x:point.x,y:point.y},s))}/>
 <PropertyInspector scope={scope} revision={revision} label="Signature dimensions" disabledReason={off?'Signature placement unavailable':undefined} unstyled={unstyled} fields={[{kind:'number',id:'width',label:'Width relative to page',value:placement.width,min:.001,max:1,step:.001},{kind:'number',id:'rotation',label:'Rotation',value:placement.rotation,min:-180,max:180,step:1,unit:'degrees'}]} onCommit={(id,value)=>guard.run('placement',(h,s)=>h.onPlacementChange({...h.placement,[id]:value},s))}/>
 <Button title={artifact&&placedArtifactId===artifact.id?'Signature stamp acknowledged':'Place signature stamp'} disabled={off||!artifact||!canPlace} unstyled={unstyled} onPress={()=>guard.run('place',(h,s)=>{if(h.artifact&&h.canPlace)return h.onPlace(h.artifact.id,h.placement,s);})}/><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}
